750|        cSize = (U32)srcSize;
751|        LZ4F_writeLE32(cSizePtr, cSize | LZ4F_BLOCKUNCOMPRESSED_FLAG);
752|        memcpy(cSizePtr+BHSize, src, srcSize);
753|    } else {
754|        LZ4F_writeLE32(cSizePtr, cSize);
