850|            memcpy(cctxPtr->tmpIn + cctxPtr->tmpInSize, srcBuffer, srcSize);
851|            srcPtr = srcEnd;
852|            cctxPtr->tmpInSize += srcSize;
853|            /* still needs some CRC */
