874|        dstPtr += LZ4F_makeBlock(dstPtr,
875|                                 srcPtr, blockSize,
876|                                 compress, cctxPtr->lz4CtxPtr, cctxPtr->prefs.compressionLevel,
877|                                 cctxPtr->cdict,
878|                                 cctxPtr->prefs.frameInfo.blockChecksumFlag);
