955|                             cctxPtr->tmpIn, cctxPtr->tmpInSize,
956|                             compress, cctxPtr->lz4CtxPtr, cctxPtr->prefs.compressionLevel,
957|                             cctxPtr->cdict,
958|                             cctxPtr->prefs.frameInfo.blockChecksumFlag);
