1014|        size_t readSize;
1015|        size_t pos = 0;
1016|        size_t decodedBytes = ress.dstBufferSize;
1017|
1018|        /* Read input */
1019|        if (nextToLoad > ress.srcBufferSize) nextToLoad = ress.srcBufferSize;
